from heapq import heappush, heappop
from collections import deque

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    # Priority queue to store (current path, current cell, visited cells)
    pq = []
    for i in range(N):
        for j in range(N):
            heappush(pq, ([grid[i][j]], (i, j), {(i, j)}))

    while pq:
        path, (i, j), visited = heappop(pq)
        if len(path) == k:
            return path

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and (ni, nj) not in visited:
                new_path = path + [grid[ni][nj]]
                new_visited = visited | {(ni, nj)}
                heappush(pq, (new_path, (ni, nj), new_visited))

    return []
