import heapq
from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Priority queue to store (path, current value, current position, visited set)
    pq = []
    for i in range(N):
        for j in range(N):
            heapq.heappush(pq, ([grid[i][j]], grid[i][j], (i, j), {(i, j)}))

    while pq:
        path, current_value, (x, y), visited = heapq.heappop(pq)

        if len(path) == k:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited:
                new_visited = visited.copy()
                new_visited.add((nx, ny))
                new_path = path + [grid[nx][ny]]
                heapq.heappush(pq, (new_path, grid[nx][ny], (nx, ny), new_visited))

    return []

